const GetAccounts = {"metadata":{"allOf":[{"type":"object","properties":{"X-Akahu-Id":{"type":"string","examples":["{{app_token}}"],"$schema":"http://json-schema.org/draft-04/schema#","description":"Your **App ID Token**."}},"required":["X-Akahu-Id"]}]},"response":{"200":{"type":"object","properties":{"success":{"type":"boolean"},"items":{"type":"array","items":{"type":"object","properties":{"_id":{"type":"string","format":"cuid","pattern":"^acc_[a-z0-9]{25,27}$","description":"A unique identifier for the account in the Akahu system. It is always prefixed by `acc_` so that you can tell that it belongs to an account.","examples":["acc_c01234567890123456789012345"]},"_migrated":{"type":"string","format":"cuid","pattern":"^acc_[a-z0-9]{25,27}$","description":"The identifier of this account's predecessor.\nThis attribute is only present if the account has been migrated to an official open banking connection from a classic Akahu connection.\n\nRead more [here](/docs/official-open-banking).","examples":["acc_c01234567890123456789012344"]},"_authorisation":{"type":"string","format":"cuid","pattern":"^authorisation_[a-z0-9]{25,27}$","description":"The authorisation identifier. Financial accounts are connected to Akahu via an authorisation with the user's financial institution. Multiple accounts can be connected during a single authorisation, causing them to have the same authorisation identifier. This identifier can also be used to link a specific account to identity data for the [party](/reference/get_parties) who completed the authorisation.","examples":["authorisation_c01234567890123456789012345"]},"_credentials":{"type":"string","deprecated":true,"description":"Deprecated: Please use `_authorisation` instead."},"connection":{"type":"object","description":"Information about the financial institution where the account is held (eg. ANZ bank).","properties":{"_id":{"type":"string","format":"cuid","pattern":"^conn_[a-z0-9]{25,27}$","description":"The connected financial institution's unique identifier. This will always be prefixed with `conn_`.","examples":["conn_cjgaac5at000001qi2yw8ftil"]},"name":{"type":"string","description":"Display name for the connected institution.","examples":["My Bank"]},"logo":{"type":"string","format":"uri","description":"A URL pointing to an image of the institution's logo.","examples":["https://cdn.akahu.nz/logos/connections/conn_cjgaac5at000001qi2yw8ftil"]},"connection_type":{"type":"string","description":"The type of integration used to connect to this institution.\n\nThis will be one of:\n- `classic` A classic Akahu connection, which uses Akahu's custom built integration to connect to the institution.\n- `official` An official open banking connection, which uses the institution's official open banking APIs.\n\n`classic` `official`","enum":["classic","official"],"examples":["official"]}},"required":["_id","name","logo","connection_type"]},"name":{"type":"string","description":"The name of this account. If the connection allows customisation, the name will be the custom name (or nickname), eg. \"Spending Account\". Otherwise Akahu falls back to the product name, eg. \"Super Saver\".","examples":["Demo Account"]},"status":{"type":"string","enum":["ACTIVE","INACTIVE"],"description":"This attribute indicates the status of Akahu's connection to this account.\n\nIt is possible for Akahu to lose the ability to authenticate with a financial institution if the user revokes Akahu's access directly via their institution, or changes their login credentials, which in some cases can cause our long-lived access to be revoked.\n\nThe account `status` will be one of:\n\n- `ACTIVE` Akahu can authenticate with the institution to retrieve data and/or initiate payments for this account.\n\n- `INACTIVE` Akahu no longer has access to this account. Your application will still be able to access Akahu's cached copy of data for this account, but this will no longer be updated by [refreshes](/docs/data-refreshes). Write actions such as payments or transfers will no longer be available. Once an account is assigned the `INACTIVE` status, it will stay this way until the user re-establishes the connection. When your application observes an account with a status of `INACTIVE`, the user should be directed back to the Akahu OAuth flow or to https://my.akahu.nz/connections where they will be prompted to re-establish the connection.\n\n`ACTIVE` `INACTIVE`","examples":["ACTIVE"]},"balance":{"type":"object","description":"The account balance","properties":{"currency":{"type":"string","description":"The (3 letter ISO 4217 currency code)[https://www.xe.com/iso4217.php] that this balance is in.","examples":["NZD"]},"current":{"type":"number","description":"The current account balance.","examples":[99.9]},"available":{"type":"number","description":"The balance that is currently available to the account holder.","examples":[99.9]},"limit":{"type":"number","description":"The credit limit for this account. For example a credit card limit or an overdraft limit. This value is only present when provided directly by the connected financial institution.","examples":[1000]},"overdrawn":{"type":"boolean","description":"A boolean indicating whether this account is in unarranged overdraft.","examples":[false]}},"required":["currency","current"]},"type":{"type":"string","enum":["CHECKING","SAVINGS","CREDITCARD","LOAN","KIWISAVER","INVESTMENT","TERMDEPOSIT","FOREIGN","TAX","REWARDS","WALLET"],"description":"Type of account, Akahu provides specific bank account types, and falls back to more general types for other types of connection.\n- `CHECKING` → An everyday spending account.\n- `SAVINGS` → A savings account.\n- `CREDITCARD` → A credit card.\n- `LOAN` → A loan account.\n- `KIWISAVER` → A KiwiSaver investment product.\n- `INVESTMENT` → A general investment product.\n- `TERMDEPOSIT` → A term deposit.\n- `FOREIGN` → An account holding a foreign currency.\n- `TAX` → An account with tax authorities.\n- `REWARDS` → An account for rewards points, e.g. Fly Buys or True Rewards.\n- `WALLET` → Available cash for investment or withdrawal from an investment provider.\n\n`CHECKING` `SAVINGS` `CREDITCARD` `LOAN` `KIWISAVER` `INVESTMENT` `TERMDEPOSIT` `FOREIGN` `TAX` `REWARDS` `WALLET`","examples":["CHECKING"]},"attributes":{"type":"array","items":{"type":"string","enum":["TRANSFER_TO","PAYMENT_TO","TRANSACTIONS","PAYMENT_FROM","TRANSFER_FROM"],"examples":["TRANSFER_FROM"],"description":"`TRANSFER_TO` `PAYMENT_TO` `TRANSACTIONS` `PAYMENT_FROM` `TRANSFER_FROM`"},"description":"The list of attributes indicates which abilities an account has. A list of:\n- `TRANSACTIONS` → account has transactions and supports retrieval of these via Akahu.\n- `TRANSFER_TO` → account can receive transfers from other accounts belonging to same set of credentials.\n- `TRANSFER_FROM` → account can initiate transfers to other accounts belonging to the same set of credentials.\n- `PAYMENT_TO` → account can receive payments from any Akahu account with the `PAYMENT_FROM` attribute.\n- `PAYMENT_FROM` → account can initiate payments to any Akahu account with the `PAYMENT_TO` attribute.","examples":["TRANSFER_TO","PAYMENT_TO","TRANSACTIONS","PAYMENT_FROM","TRANSFER_FROM"]},"formatted_account":{"type":"string","description":"If the account has a well defined account number (eg. a bank account number, or credit card number) this will be defined here with a standard format across connections. Credit cards will have at least 8 digits redacted.","examples":["12-1234-1234567-12"]},"meta":{"type":"object","description":"Metadata regarding this account","additionalProperties":true,"properties":{"holder":{"type":"string","description":"The account holder name","examples":["MR DEMO HOLDER & MS DEMO HOLDER"]},"has_unlisted_holders":{"type":"boolean","description":"Indicates if the account has other holders that are not listed in the holder field. This only applies to official open banking connections where the institution indicates a joint account, but only provides the authorising party's name.","examples":[false]},"loan_details":{"type":"object","description":"Details about a loan account, if available.","properties":{"purpose":{"type":"string","description":"The purpose of the loan, if we can't determine the purpose, this will be `UNKNOWN`\n\n`HOME` `PERSONAL` `BUSINESS` `UNKNOWN`","enum":["HOME","PERSONAL","BUSINESS","UNKNOWN"],"examples":["HOME"]},"type":{"type":"string","description":"The type of loan, if we can't determine the type, this will be `UNKNOWN`\n\n`TABLE` `REDUCING` `REVOLVING` `UNKNOWN`","enum":["TABLE","REDUCING","REVOLVING","UNKNOWN"],"examples":["TABLE"]},"interest":{"type":"object","description":"Interest rate information for the loan.","properties":{"rate":{"type":"number","description":"The interest rate on the loan.","examples":[4.5]},"type":{"type":"string","description":"The type of interest rate.\n\n`FIXED` `FLOATING`","enum":["FIXED","FLOATING"],"examples":["FIXED"]},"expires_at":{"type":"string","format":"date-time","description":"When this interest rate expires, if available.","examples":["2021-01-01T12:00:00.000Z"]}},"required":["rate","type"]},"is_interest_only":{"type":"boolean","description":"Is the loan currently in an interest only period?","examples":[false]},"interest_only_expires_at":{"type":"string","format":"date-time","description":"When the interest only period expires, if available.","examples":["2021-01-01T12:00:00.000Z"]},"term":{"type":"object","description":"The duration/term of the loan for it to be paid to completion from the start date of the loan.","properties":{"years":{"type":"number","description":"The number of years the loan is for.","examples":[30]},"months":{"type":"number","description":"The number of months the loan is for.","examples":[5]}}},"matures_at":{"type":"string","format":"date-time","description":"When the loan matures, if available.","examples":["2021-01-01T12:00:00.000Z"]},"initial_principal":{"type":"number","description":"The loan initial principal amount, this was the original amount borrowed.","examples":[100000]},"repayment":{"type":"object","description":"Loan repayment information if available.","properties":{"frequency":{"type":"string","description":"The frequency of the loan repayment.\n\n`WEEKLY` `FORTNIGHTLY` `MONTHLY` `QUARTERLY` `BIANNUALLY` `ANNUALLY`","enum":["WEEKLY","FORTNIGHTLY","MONTHLY","QUARTERLY","BIANNUALLY","ANNUALLY"],"examples":["MONTHLY"]},"next_date":{"type":"string","format":"date-time","description":"The next repayment date, if available.","examples":["2021-01-01T12:00:00.000Z"]},"next_amount":{"type":"number","description":"The next instalment amount.","examples":[1000]}},"required":["next_amount"]}},"required":["purpose","type","interest","is_interest_only"]}}},"refreshed":{"type":"object","description":"Akahu can refresh different parts of an account's data at different rates. The timestamps in the `refreshed` object tell you when that account data was last updated. This can be thought of as \"Akahu's view of the account (balance/metadata/transactions) is up to date as of \\$TIME\".","properties":{"balance":{"type":"string","format":"date-time","description":"The ISO 8601 timestamp when the balance was last retrieved","examples":["2021-01-01T12:00:00.000Z"]},"meta":{"type":"string","format":"date-time","description":"The ISO 8601 timestamp when other account metadata was last retrieved (any property apart from balance)","examples":["2021-01-01T12:00:00.000Z"]},"transactions":{"type":"string","description":"The ISO 8601 timestamp when we last checked for and processed any new transactions. This flag may be missing when an account has first connected, as it takes a few seconds for new transactions to be processed.","examples":["2021-01-01T12:00:00.000Z"]},"party":{"type":"string","description":"The ISO 8601 timestamp when we last fetched identity data about the party who has authenticated with the financial institution when connecting this account.","examples":["2021-01-01T12:00:00.000Z"]}}}},"required":["_id","_credentials","_authorisation","connection","name","status","type","attributes"]}}},"$schema":"http://json-schema.org/draft-04/schema#"},"400":{"type":"object","properties":{"success":{"type":"boolean","examples":[false]},"message":{"type":"string","examples":["Invalid Content-Type"]}},"$schema":"http://json-schema.org/draft-04/schema#"},"401":{"type":"object","properties":{"success":{"type":"boolean","examples":[false]},"message":{"type":"string","examples":["Permission Denied"]}},"$schema":"http://json-schema.org/draft-04/schema#"},"403":{"type":"object","properties":{"success":{"type":"boolean","examples":[false]},"message":{"type":"string","examples":["Forbidden"]}},"$schema":"http://json-schema.org/draft-04/schema#"},"500":{"type":"object","properties":{"success":{"type":"boolean","examples":[false]},"message":{"type":"string","examples":["Something went wrong"]}},"$schema":"http://json-schema.org/draft-04/schema#"}}} as const
